const queries = [
  "relationSupportByLanguage mergeLanguageSupport ooRelationSupport per-language advertised capability matrix",
  "supportsCallExtraction hardcoded language switch and generic call relation extraction runtime",
  "profile spec emits relation extractor generic per parsed body actual emission",
  "why omit SIMILAR_TO CONSTRUCTS TESTS from advertised capabilities reliability experimental"
];
const out = [];
for (const q of queries) {
  const r = await tools.exec_command({cmd:`./entire-graph search --repo . --query ${JSON.stringify(q)} --format text --top-k 10 --max-context-bytes 26000`,"workdir":"/Users/thomi/Projects/entire-graph","yield_time_ms":30000,"max_output_tokens":26000});
  out.push(`QUERY: ${q}\n${r.output}`);
}
text(out.join("\n\n"));
